fa0429696aeeebe0a8e1e8c39b80b5192e977fffa9ce331c6706a9856c62753","veredicto":"PASS","juez":"Claude independiente 2026-11-24 09:20 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":0.8,"observacion":"Alcance administrativo no cubierto como superficie; roles, permisos, tablas y pantalla por resolver."},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":596,"familia":"GOVERNANCE_APPROVAL","diferencias":"Contraste funcional: BLOQUEAR cambio de activación, parámetros, vigencia o alcance de beneficio LF sin configuración canónica, autorización efectiva y trazabilidad; cliente final no es autoridad. Roles, permisos, tablas y pantallas quedan por resolver. Observación del juez: Alcance administrativo no cubierto como superficie; roles, permisos, tablas y pantalla por resolver.","residual":"Alcance administrativo no cubierto como superficie; roles, permisos, tablas y pantalla por resolver.","complementa":null},{"codigo":"S13-C16","version":1,"eval_id":1010,"hash_version_atestado":"f454f7ef067e1377a1ea5ac4a5a5c0f07775a40ed6a9f96a65252580650f7418","hash_paquete_atestado":"46f3f182a39abc3c89d4eb637180bb50d490693e379b107674c5e795038cdd63","veredicto":"PASS","juez":"Claude independiente 2026-11-24 09:20 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":0.8,"observacion":"Omite estructura base de bloques: saludo/contexto, siguiente acción principal, situaciones coexistentes, beneficio/campaña, orientación y ayuda contextual."},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":601,"familia":"LOADING_EMPTY_ERROR_STATES","diferencias":"Contraste funcional: BLOQUEAR composición de Inicio que muestre bloque sin dato autoritativo/no aplicable, deje espacio vacío tras ocultarlo o permita beneficio/campaña desplazar acción financiera P0/P1; jerarquía de bloques según contexto server-side. Observación del juez: Omite estructura base de bloques: saludo/contexto, siguiente acción principal, situaciones coexistentes, beneficio/campaña, orientación y ayuda contextual.","residual":"","complementa":null},{"codigo":"S13-C17","version":1,"eval_id":1011,"hash_version_atestado":"9ab4dc3760c4ece11a819a0da2097ac530ae97a6d2c2eebbd7898be8ab0d2982","hash_paquete_atestado":"ce8379f20f6b014ff16e0b9e3dce8120d2ff0e07d862c9bba0bb3ce9961ad393","veredicto":"PASS","juez":"Claude independiente 2026-11-24 09:20 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":655,"familia":"TRANSITIONS","diferencias":"Contraste funcional: BLOQUEAR transición AUTH_FLOW B2B no registrada en lf_ops.estados_transiciones o impuesta por cliente; servidor determina origen/destino y resultado; MFA_REQUIRED/AUTHENTICATED proyectan estado y INVALID_CREDENTIALS/RATE_LIMITED/ACCESS_DENIED/SERVICE_UNAVAILABLE preservan estado no autenticado o MFA vigente según corresponda.","residual":"","complementa":null}]$pack$::jsonb) LOOP
 cd:=p->>'codigo'; lid:=(p->>'legada_id')::int;
 SELECT id,regla,version,hash_paquete INTO e FROM lf_ops.nucleo_evaluaciones WHERE regla=cd AND version=(p->>'version')::int ORDER BY id DESC LIMIT 1;
 IF ((SELECT count(*) FROM lf_ops.reglas)=586 AND e.id IS DISTINCT FROM (p->>'eval_id')::bigint) OR e.hash_paquete IS DISTINCT FROM p->>'hash_paquete_atestado' OR (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=e.version)<>8 OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version AND estado='CANDIDATA' AND hash=p->>'hash_version_atestado') THEN RAISE EXCEPTION 'S13_ATTESTATION_DRIFT %',cd; END IF;
 h:=lf_ops.nucleo_hash_paquete_v1(cd,e.version);
 IF h IS DISTINCT FROM e.hash_paquete THEN RAISE EXCEPTION 'S13_HASH_DRIFT %',cd; END IF;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto',p->>'veredicto','puntajes',p->'puntajes','juez',p->>'juez','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','sandbox/lf_contract_gate_test/nucleo_ci/nucleo_s13_juicios_17_v1.json#'||cd);
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S13_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision'<>'AUTO' THEN RAISE EXCEPTION 'S13_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado'<>'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S13_PROMOTION_FAIL % %',cd,ans; END IF;
 pub:=pub+1;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 IF EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada WHERE legacy_id=lid AND estado_cobertura='REEMPLAZADA') THEN RAISE EXCEPTION 'S13_COVERAGE_DRIFT %',lid; END IF;
 IF p->>'complementa' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada c JOIN lf_ops.nucleo_regla_versiones v ON v.regla=c.nucleo_codigo AND v.version=c.version_nucleo WHERE c.legacy_id=lid AND c.nucleo_codigo=p->>'complementa' AND c.estado_cobertura='PARCIAL' AND v.estado='PUBLICADA') THEN RAISE EXCEPTION 'S13_COMPLEMENT_DRIFT %',lid; END IF;
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 SELECT descripcion INTO new_desc FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version;
 residual:=coalesce(p->>'residual',''); diff:=p->>'diferencias'||CASE WHEN residual<>'' THEN ' Residual: '||residual ELSE '' END;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,e.version,CASE WHEN residual='' THEN 'REEMPLAZADA' ELSE 'PARCIAL' END,diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||new_desc||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente S13 2026-11-24 05:55','limite_aceptacion','Cobertura funcional; binding runtime no certificado'),h,'GPT / Claude S13 independiente');
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S13_SOURCE_MISSING %',lid; END IF;
 n:=n+1;
 END LOOP;
 IF n<>17 OR pub<>17 OR ((SELECT count(*) FROM lf_ops.reglas)=586 AND links<>17) OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.reglas t) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones t) IS DISTINCT FROM b_dep THEN RAISE EXCEPTION 'S13_READBACK_FAIL n=% pub=% links=%',n,pub,links; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S13_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S13_PASS 17 JUICIOS 17 AUTO links=% DPIG03=0',links;
END $s13$;
COMMIT;
